以下是您需要的，一段高技巧的C代码示例：

```c
/* 高技巧C代码：无分支绝对值 + 位运算技巧集合
 * 编译: gcc -O2 -Wall -Wextra -o tricks tricks.c
 * 说明: 展示几个经典且实用的底层位运算技巧，
 *       包括无分支绝对值、位计数、字节序探测、
 *       快速除以2的幂的舍入、以及XOR交换等。
 */

#include <stdio.h>
#include <stdint.h>
#include <limits.h>

/* 技巧1: 无分支求绝对值 (对int)
 * 原理: mask = x >> 31 (算术右移) 得到全0或全1
 *       (x + mask) ^ mask
 *       当x>=0: mask=0, 结果=x
 *       当x<0 : mask=-1, (x-1)^(-1) = -(x) = -x
 * 注意: 对 INT_MIN 行为未定义，实际通常得 INT_MIN */
static inline int abs_nobranch(int x)
{
    int mask = x >> (sizeof(int) * CHAR_BIT - 1);
    return (x + mask) ^ mask;
}

/* 技巧2: 统计二进制中1的个数 (Brian Kernighan 算法)
 * 每次 x &= x-1 会消掉最低位的1，循环次数=1的个数 */
static inline int popcount(uint32_t x)
{
    int count = 0;
    while (x) {
        x &= x - 1;
        ++count;
    }
    return count;
}

/* 技巧3: 探测主机字节序 (小端/大端) */
static inline int is_little_endian(void)
{
    uint16_t v = 0x0001;
    return *(uint8_t *)&v == 1;
}

/* 技巧4: 向上对齐到2的幂倍数
 * align 必须是2的幂 */
static inline size_t align_up(size_t n, size_t align)
{
    return (n + align - 1) & ~(align - 1);
}

/* 技巧5: 交换两个整数（不使用临时变量）
 * 经典 XOR 交换，注意 a 与 b 不能是同一地址 */
static inline void xor_swap(int *a, int *b)
{
    if (a != b) {
        *a ^= *b;
        *b ^= *a;
        *a ^= *b;
    }
}

/* 技巧6: 判断一个数是否是2的幂 */
static inline int is_power_of_two(uint32_t x)
{
    return x && !(x & (x - 1));
}

/* 技巧7: 取最低位的1所对应的值 */
static inline uint32_t lowest_bit(uint32_t x)
{
    return x & (~x + 1);   /* x & -x */
}

/* 技巧8: 快速求下一个2的幂 (>= x)
 * 通过位扩展把最高位以下的位全部填1，再+1 */
static inline uint32_t next_power_of_two(uint32_t x)
{
    x--;
    x |= x >> 1;
    x |= x >> 2;
    x |= x >> 4;
    x |= x >> 8;
    x |= x >> 16;
    return x + 1;
}

int main(void)
{
    printf("abs_nobranch(-42)      = %d\n", abs_nobranch(-42));
    printf("popcount(0xF0F0F0F0)   = %d\n", popcount(0xF0F0F0F0u));
    printf("is_little_endian       = %d\n", is_little_endian());
    printf("align_up(13, 8)        = %zu\n", align_up(13, 8));
    printf("is_power_of_two(64)    = %d\n", is_power_of_two(64));
    printf("is_power_of_two(63)    = %d\n", is_power_of_two(63));
    printf("lowest_bit(0x50)       = 0x%X\n", lowest_bit(0x50));
    printf("next_power_of_two(17)  = %u\n", next_power_of_two(17));

    int a = 3, b = 7;
    xor_swap(&a, &b);
    printf("after xor_swap: a=%d b=%d\n", a, b);

    return 0;
}
```

### 代码亮点说明

1. **无分支绝对值**：用算术右移生成掩码，`(x + mask) ^ mask` 同时处理正负，避免 `if/else` 带来的分支预测开销，适合性能敏感场景。

2. **Kernighan 位计数**：`x &= x - 1` 每次清除最低位的 1，循环次数等于 1 的个数，比逐位扫描快得多。

3. **运行期字节序探测**：通过 `uint16_t` 与 `uint8_t*` 别名判断，简单可靠（严格来说别名访问 `uint8_t` 是允许的，因为 `char` 类型可别名任意对象）。

4. **向上对齐**：`(n + align - 1) & ~(align - 1)` 是内存分配器、DMA 缓冲对齐的标准写法。

5. **XOR 交换**：经典技巧，附加了 `a != b` 保护，避免同一地址时自身清零的陷阱。

6. **`x & -x`**：提取最低有效位，在树状数组（Fenwick Tree）等算法中广泛使用。

7. **`next_power_of_two`**：通过位扩散把最高位以下填满 1，再 +1 进位，常用于哈希表扩容、环形缓冲区大小选择。

整段代码均使用 `static inline`，编译后几乎零函数调用开销，适合嵌入底层库或算法实现中。
